system.script:
module.exports = async function (data) {
    const readResult = data.$last;
    const items = Array.isArray(readResult) ? readResult : readResult ? [readResult] : [];
    const task = items[0];
    if (!task || task.Status !== "done" || !task.Recurring) return [];

    const shiftDate = (dateString, interval) => {
        if (!dateString) return null;
        const d = new Date(dateString);
        if (Number.isNaN(d.getTime())) return null;
        const int = String(interval).toLowerCase();
        if (int.includes("day")) d.setDate(d.getDate() + 1);
        else if (int.includes("week")) d.setDate(d.getDate() + 7);
        else if (int.includes("month")) d.setMonth(d.getMonth() + 1);
        else if (int.includes("year")) d.setFullYear(d.getFullYear() + 1);
        else return null;
        return d.toISOString();
    };

    const nextStart = shiftDate(task.Start, task.Recurring);
    const nextEnd = shiftDate(task.End, task.Recurring);
    if (!nextStart && !nextEnd) return [];

    return [{
        Title: task.Title || "Повторяющаяся задача",
        Status: "to_do",
        Recurring: task.Recurring,
        Start: nextStart,
        End: nextEnd
    }];
};

module.exports = async function (data) {
    const OWNER_UUID = "2487b299-3d6b-4b41-8adf-7f79e67eb3eb";
    const created = data.$last;
    const createdIds = Array.isArray(created) ? created : created ? [created] : [];
    if (createdIds.length === 0) return [];
    const newTaskId = typeof createdIds[0] === "object" ? createdIds[0].id : createdIds[0];
    const userId = data.$accountability?.user || data.$trigger?.accountability?.user || OWNER_UUID;
    if (!userId) return [];

    let taskTitle = "Повторяющаяся задача";
    let taskStart = null;
    for (const nodeResult of Object.values(data)) {
        if (!Array.isArray(nodeResult) || !nodeResult[0] || typeof nodeResult[0] !== "object") continue;
        if (nodeResult[0].Title && nodeResult[0].Status === "to_do") {
            taskTitle = nodeResult[0].Title;
            taskStart = nodeResult[0].Start;
            break;
        }
    }
    const startDate = taskStart ? new Date(taskStart).toLocaleDateString("ru-RU") : "неизвестную дату";

    return [{
        recipient: userId,
        sender: null,
        status: "inbox",
        subject: "🔁 Повторяющаяся задача",
        message: `Создана карточка «${taskTitle}». Запланирована на ${startDate}`,
        collection: "Tasks",
        item: String(newTaskId)
    }];
};
